INSERT INTO fut_accounts VALUES(1,'main','PS5','FC27','2026-09-19 fut.gg GG Club 조회: 활성 스쿼드 「Hobong」 4-2-3-1 · fut.gg 계산 케미 33/33 — 우리 케미 계산기 결과와 일치(검증). 보유 47명(09-18 싱크 상태) · 케미 스타일 전원 미적용(Basic 250 / GK Basic 273) [2026-09-23] 시즌패스: 사용자 확인 「7 미만」·프리미엄 미구매. ⚠️ season_pass_level=0은 정확한 값이 아니라 **보수적 하한**이다 — 현행 최저 레벨형 진화가 SP 7이라 판정 결과는 같고, 잘못 열리는 것보다 잘못 잠기는 쪽이 안전하다. 정확한 레벨을 알게 되면 갱신할 것. [2026-09-26] 시즌패스 레벨 **7 달성**(사용자 보고) — Striker Glow Up [SP 7] 해금 확인. ⚠️ 프리미엄은 여전히 미구매라 [SP+ N] 진화는 잠긴 채다. ⚠️ 레벨은 계속 오르므로 SP 11·27짜리 판정을 맞추려면 그때 다시 적어야 한다.','2026-09-18',7,0,'2026-09-23');
